<?php require "../config/auth.php";require "../config/database.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$vals=[];foreach(["judul", "penulis", "tanggal", "kategori", "ringkasan", "thumbnail", "isi"] as $c)$vals[]=$_POST[$c]??"";$pdo->prepare("INSERT INTO berita (judul,penulis,tanggal,kategori,ringkasan,thumbnail,isi) VALUES (?,?,?,?,?,?,?)")->execute($vals);header("Location:berita.php");exit;}if(isset($_GET["delete"])){$pdo->prepare("DELETE FROM berita WHERE id=?")->execute([(int)$_GET["delete"]]);header("Location:berita.php");exit;}$rows=$pdo->query("SELECT * FROM berita ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Berita | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Berita</h2><a href="index.php">Dashboard</a></div><div class="card p-4 my-4"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Judul</label><input name="judul" class="form-control"></div><div class="col-md-6"><label class="form-label">Penulis</label><input name="penulis" class="form-control"></div><div class="col-md-6"><label class="form-label">Tanggal</label><input name="tanggal" class="form-control"></div><div class="col-md-6"><label class="form-label">Kategori</label><input name="kategori" class="form-control"></div><div class="col-md-6"><label class="form-label">Ringkasan</label><input name="ringkasan" class="form-control"></div><div class="col-md-6"><label class="form-label">Thumbnail</label><input name="thumbnail" class="form-control"></div><div class="col-md-6"><label class="form-label">Isi</label><input name="isi" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Tambah</button></div></form></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>ID</th><th>judul</th><th>penulis</th><th>tanggal</th><th>kategori</th><th>ringkasan</th><th>thumbnail</th><th>isi</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["judul"])?></td><td><?=e($r["penulis"])?></td><td><?=e($r["tanggal"])?></td><td><?=e($r["kategori"])?></td><td><?=e($r["ringkasan"])?></td><td><?=e($r["thumbnail"])?></td><td><?=e($r["isi"])?></td><td><a class="btn btn-sm btn-danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Hapus data?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>